// Período: do dia 1 do mês até hoje (horário de Brasília). Nos 3 primeiros dias do mês
// reconfere também o mês anterior (vendas lançadas ou canceladas depois).
const now = new Date(new Date().toLocaleString('en-US', {timeZone: 'America/Sao_Paulo'}));
const pad = (n) => String(n).padStart(2, '0');
const iso = (d) => d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
const start = new Date(now.getFullYear(), now.getMonth() - (now.getDate() <= 3 ? 1 : 0), 1);

// Cole SÓ o token da unidade, sem a palavra Bearer.
const token = 'COLE_AQUI_TOKEN_24H';
// Só venda nova. Renovação não entra (o painel recusa).
return [
  {json: {unidade: '24h', token, empresaId: 1, de: iso(start), ate: iso(now), produto: 'MATRÍCULA', codigoProduto: 10}},
  {json: {unidade: '24h', token, empresaId: 1, de: iso(start), ate: iso(now), produto: 'REMATRÍCULA', codigoProduto: 11}},
];

// Casa cada resposta com a consulta que a gerou e monta o corpo que o painel espera.
const base = $('Configurar Santarem 24h').all();
const feitos = [];
const falhas = [];
$input.all().forEach((it, i) => {
  const b = base[i].json;
  const r = it.json;
  const status = r.statusCode ?? 0;
  const body = r.body ?? {};
  const content = Array.isArray(body.content) ? body.content : null;
  if (status === 200 && content !== null) {
    feitos.push({json: {
      unidade: b.unidade, produto: b.produto, recebidos: content.length,
      corpo: {
        unidade: b.unidade, produto: b.produto, data_inicio: b.de, data_fim: b.ate,
        total: body.totalElements ?? null, contratos: content,
      },
    }});
  } else {
    falhas.push(b.produto + ': HTTP ' + status + ' ' + JSON.stringify(body).slice(0, 200));
  }
});
// Falhou tudo: deixa a execução vermelha (aparece em Execuções). Falha parcial
// (ex.: 429 numa das duas) só repete no próximo ciclo.
if (feitos.length === 0 && falhas.length) throw new Error(falhas.join(' | '));
return feitos;

